contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Fund c by sending Ether through sendMoney to c itself (hits its fallback).
        c.sendMoney(address(c), amount, ""); if (__ESBMC_reverted()) return;
        uint balC = address(c).balance;
        require(amount <= balC);
        uint balTestBefore = address(this).balance;
        bool reverted;
        c.sendMoney(address(this), amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(!reverted && address(this).balance == balTestBefore + amount && address(c).balance + amount == balC);
    }
    receive() external payable {}
}

